from pathlib import Path
O=Path(__file__).resolve().parent
p=O/'write_sciences.py';t=p.read_text()
rows=[
('normal','Pour la leçon : quelle est la sémiologie fondamentale et analytique ?','<p>Le filtre normal limite le passage des protéines, puis le tubule proximal récupère une grande partie des protéines filtrées. L’urine contient aussi des protéines sécrétées, dont l’uromoduline. Chez l’adulte, la limite physiologique de protéines totales est autour de150mg/j ; l’albumine est normalement inférieure à30mg/j. Ces repères ne sont pas interchangeables.</p><p>La normalité précise analyte, unité, méthode et population. Un débitG1 ouG2 ne démontre pas l’intégrité du filtre ; une albuminurie pathologique persistante peut établir un dommage malgré filtration conservée. Inversement,G2 isolé sans marqueur ne suffit pas à définir uneMRC.</p>',('CH-PROT-MEC','EU-PROT-DEF','INT-CKD-DEF'),'sediment'),
('signs','Décrire un résultat avant de le qualifier d’isolé','<p>Noter quantité, composition, recueil et dates. Une urine mousseuse ne quantifie pas les protéines ; une bandelette positive ne donne ni perte quotidienne ni cause. La présentation peut être sans plainte. Rechercher sang visible, baisse de diurèse, œdèmes, variation de poids, dyspnée ou symptômes systémiques.</p><p>Le caractère isolé se vérifie avec pression, fonction, sédiment et albumine sanguine. Une anomalie associée oblige à requalifier le syndrome. Effort, fièvre, infection, posture et contamination peuvent modifier un prélèvement ; une seule mesure ne prouve ni persistance ni bénignité.</p>',('EU-PROT-WORKUP','INT-CKD-URINE','CH-PROT-REF'),None),
('mechanisms','Relier composition et compartiment','<p>La fuite glomérulaire produit souvent une protéinurie à prédominance albuminurique. Un défaut de réabsorption proximale augmente les petites protéines ; une surcharge circulante, par exemple en chaînes légères, peut saturer cette récupération. Ces mécanismes peuvent se combiner. Une faible fraction d’albumine n’exclut donc pas une maladie importante.</p><p>La composition explique pourquoi une bandelette centrée sur l’albumine peut manquer une protéinurie de surcharge. Une lésion de sclérose ne se confond pas avec une inflammation ; le mécanisme, le tissu et la trajectoire déterminent la suite plutôt que le seul total.</p>',('CH-PROT-MEC','EU-PROT-DEF','EU-HISTO'),None),
('examination','Prélever et examiner de manière comparable','<p>Confirmer une positivité semi-quantitative parACR ouPCR au laboratoire. Préférer le premier prélèvement matinal à mi-jet, préciser effort, infection, menstruations et méthode. Chez l’enfant, les recommandations demandent les deux rapportsACR etPCR sur le premier matin. Le rapport réduit l’effet de dilution mais dépend encore de l’excrétion de créatinine.</p><p>Mesurer pression, poids, volume et fonction ; examiner les signes orientés par l’histoire. La recherche de posture se fait dans un contexte compatible avec un protocole adapté. Un résultat discordant, persistant ou associé à un signe d’alerte impose une réévaluation.</p>',('INT-CKD-URINE','EU-PROT-WORKUP','CH-SGN-REF'),None),
('interpretation','Interpréter analyte, unité et durée','<p>ACR etPCR ont des numérateurs différents. Un total élevé avec une albumine faible oriente vers une composante non albuminurique sans donner seul sa cause. Une concentration enmg/L n’est pas une excrétion enmg/j. Les rapports permettent une estimation, pas une mesure certaine de la perte quotidienne de chaque personne.</p><p>Une masse musculaire faible, une fonction instable ou une excrétion de créatinine inhabituelle modifie leur relation avec une collecte chronométrée. La persistance et la trajectoire complètent la valeur. Un changement appelle une explication avant d’être qualifié de guérison ou de poussée immune.</p>',('INT-CKD-URINE','CH-PROT-METHOD','CH-PROT-MEC','INT-CKD-RISK'),None),
('differentials','Écarter les raccourcis de localisation','<p>La protéinurie peut être transitoire, orthostatique ou permanente. Une orthostatique confirmée avec profil concordant n’appelle pas automatiquement de biopsie ; l’âge seul ne la démontre pas. Infection, contamination et hématurie abondante peuvent modifier la mesure.</p><p>Parmi les atteintes persistantes, confronter mécanismes glomérulaires,tubulaires et de surcharge, maladies systémiques, médicaments et famille. Un aspectFSGS peut avoir plusieurs causes. Une discordance entre une ancienne étiquette et la présentation actuelle justifie de rouvrir le diagnostic.</p>',('EU-PROT-WORKUP','CH-PROT-MEC','EU-HISTO','EU-ALPORT-GEN','INT-CKD-DRUG'),None),
('urgency','Reconnaître une présentation qui n’est plus simplement isolée','<p>Une dégradation rapide de fonction avec sédiment néphritique nécessite une exploration rapide. Dyspnée, oligurie, hypertension avec retentissement ou manifestations systémiques menaçantes changent la priorité. La répétition destinée à confirmer une protéinurie ne doit pas retarder la sécurisation.</p><p>Les repères d’orientation de Thurgau et duCUEN portent notamment sur une protéinurie permanente importante ; laSGN ajoute les critères de cause inconnue, progression, hématurie glomérulaire et autres complications. Un seuil de consultation n’est pas un seuil universel de biopsie ou de dialyse.</p>',('CH-PROT-REF','EU-PROT-WORKUP','CH-SGN-REF','CH-HUG-ORIENT'),None),
('limits','Adapter les conclusions à la population','<p>Les seuils de protéines totales de l’adulte ne se transposent pas automatiquement à l’enfant. Pression, croissance et nutrition ont des références propres. Grossesse, fragilité, masse musculaire et fonction instable influencent mesures et prescriptions. UneFI produit peut être plus restrictive qu’une recommandation de classe.</p><p>La biopsie échantillonne le rein, la génétique a des limites et le rapport urinaire n’est pas une collecte24h certaine. Une photographie montre un champ, pas la totalité de l’activité ni la proportion globale de glomérules lésés. Les incertitudes restent visibles dans le plan.</p>',('INT-CKD-URINE','INT-CKD-TX','EU-HISTO','EU-ALPORT-GEN','FI-FORXIGA'),None),
('sources','Attribuer les méthodes et les décisions','<p>Le cadre suisse contemporain deMRC vient du guideSGN17.03.2025. La ficheThurgau non datée complète les méthodes et l’orientation ; la revueRMS2012 est utilisée pour les mécanismes du filtre et du tubule, sans reprendre ses anciennes cibles ou formulations quantitatives incohérentes.</p><p>CUEN2025 décrit normalité, composition, facteurs transitoires et parcours diagnostique. KDIGO2024 précise confirmation matinale, facteurs de variation et limites des rapports, avec distinctions pédiatriques. Les cinqFI exactes déterminent doses et populations lorsque leur indication existe. Les lectures ciblées et réutilisations du même bloc sont attribuées dans le ledger ; aucun document complet ni validation humaine n’est inventé.</p>',('CH-SGN-PEC','CH-PROT-METHOD','CH-PROT-MEC','EU-PROT-DEF','EU-PROT-WORKUP','INT-CKD-URINE','FI-RAMIPRIL'),None)
]
start=t.index("s=sem('normal'");end=t.index("c+=sci('semio',s)",start)
code=''
for i,(k,title,body,refs,fig) in enumerate(rows):
 code+=('s=' if i==0 else 's+=')+'sem('+repr(k)+','+repr(title)+','+repr(body)+(('+figure('+repr(fig)+')') if fig else '')+','+repr(refs)+')\n'
t=t[:start]+code+t[end:]
t=t.replace('Le syndrome chronique reste un profil de parenchyme rénal, sans exclure une complication dans un autre compartiment.','La localisation de la protéinurie ne se déduit pas du code ; une cause tubulaire ou de surcharge et une anomalie associée restent possibles.')
t=t.replace('Une atteinte glomérulaire chronique peut résulter','Une atteinte glomérulaire peut résulter').replace('Un syndrome chronique ne doit pas effacer','Une présentation isolée ne doit pas effacer')
t=t.replace("('CH-HUG-DEF','EU-HEMAT','INT-GN-GENERAL','INT-CKD-DEF','INT-CKD-RISK'))", "('CH-PROT-METHOD','EU-PROT-DEF','INT-CKD-URINE','CH-HUG-DEF','EU-HEMAT','INT-GN-GENERAL','INT-CKD-DEF','INT-CKD-RISK'))")
t=t.replace('Le rapport albumine/créatinine et le rapport protéines/créatinine ont des numérateurs différents.', 'Le premier prélèvement du matin à mi-jet est préféré ; chez l’enfant,ACR etPCR se complètent. Effort,infection,menstruations et excrétion de créatinine influencent la mesure. Le rapport albumine/créatinine et le rapport protéines/créatinine ont des numérateurs différents.')
t=t.replace("('CH-HUG-DEF','INT-CKD-DEF','INT-CKD-DRUG','INT-GN-GENERAL','NORMAL-FILTRE'))", "('CH-PROT-MEC','EU-PROT-DEF','INT-CKD-URINE','CH-HUG-DEF','INT-CKD-DEF','INT-CKD-DRUG','INT-GN-GENERAL','NORMAL-FILTRE'))")
t=t.replace('La créatinine est un marqueur indirect de filtration ; sa concentration dépend aussi de facteurs non rénaux.', 'Un déficit de réabsorption proximale ou une surcharge en protéines circulantes peut produire une protéinurie non majoritairement albuminurique. La discordanceACR/RPC appelle une enquête de composition. La créatinine est un marqueur indirect de filtration ; sa concentration dépend aussi de facteurs non rénaux.')
t=t.replace("('NORMAL-FILTRE','INT-CKD-TX','INT-CKD-RISK'", "('NORMAL-FILTRE','CH-PROT-MEC','INT-CKD-URINE','INT-CKD-TX','INT-CKD-RISK'")
p.write_text(t)
p=O/'write_pharmacology.py';t=p.read_text().replace('Les cinq produits ci-dessous illustrent la néphroprotection, le contrôle tensionnel et la gestion d’œdèmes dans leurs cadres précis.', 'Les cinq produits ci-dessous illustrent des décisions conditionnelles de néphroprotection, de pression ou d’œdèmes. Une protéinurie réellement isolée n’impose pas tous ces traitements ; pression élevée ou œdèmes obligent à réviser la présentation et à préciser leur mécanisme.');t=t.replace('Aucun n’est un traitement universel du syndrome N06.', 'Aucun n’est une prescription universelle deN06. Une orthostatique confirmée et concordante ne justifie pas un traitement rénal automatique.');t=t.replace("('CH-SGN-PEC','INT-CKD-TX','INT-CKD-DRUG','FI-RAMIPRIL','FI-COSAAR'))", "('EU-PROT-WORKUP','CH-SGN-PEC','INT-CKD-TX','INT-CKD-DRUG','FI-RAMIPRIL','FI-COSAAR'))",1);p.write_text(t)
